SITE_HTML = base64.b64decode(''.join(_SITE_B64)).decode('utf-8')
ADMIN_JS = base64.b64decode(''.join(_ADMIN_B64)).decode('utf-8')

# Only the assets folder is public. Never expose server.py, the database or secrets.
app = Flask(__name__, static_folder=None)  # everything is inside this one file
app.config['MAX_CONTENT_LENGTH'] = 400 * 1024

OWNER_EMAIL = os.getenv('NR_OWNER_EMAIL', 'naija.republic.rp@gmail.com').strip()
SMTP_HOST = os.getenv('NR_SMTP_HOST', 'smtp.gmail.com').strip()
SMTP_PORT = int(os.getenv('NR_SMTP_PORT', '587'))
SMTP_USER = os.getenv('NR_SMTP_USER', OWNER_EMAIL).strip()
SMTP_PASSWORD = os.getenv('NR_SMTP_PASSWORD', '').replace(' ', '')
EMAIL_FROM = os.getenv('NR_EMAIL_FROM', SMTP_USER).strip()
# The game APK is hosted on Google Drive. People are sent there after the launch countdown ends.
APK_URL = os.getenv('NR_APK_URL', 'https://drive.google.com/file/d/1X-sdjx4pw5DJAM9dtdT5VZYNC9ywTTx1/view?usp=drivesdk').strip()


def send_notice(subject, body, reply_to=None, customer_copy=None):
    if not all([OWNER_EMAIL, SMTP_HOST, SMTP_USER, SMTP_PASSWORD, EMAIL_FROM]):
        raise RuntimeError('Email service is not configured yet. Please try again later.')
    msg = EmailMessage(); msg['Subject'] = subject; msg['From'] = EMAIL_FROM; msg['To'] = OWNER_EMAIL
    if reply_to: msg['Reply-To'] = reply_to
    msg.set_content(body)
    with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=20) as smtp:
        smtp.ehlo(); smtp.starttls(); smtp.login(SMTP_USER, SMTP_PASSWORD); smtp.send_message(msg)
        if customer_copy:
            copy = EmailMessage(); copy['Subject'] = 'NAIJA REPUBLIC RP — We received your request'; copy['From'] = EMAIL_FROM; copy['To'] = customer_copy
            copy.set_content('Thank you. We have received your request and the NAIJA REPUBLIC RP team will review it.\n\n' + body)
            smtp.send_message(copy)


def payload():
    data = request.get_json(silent=True) or {}
    return {str(k): str(v).strip()[:4000] for k, v in data.items()}


def required(data, fields):
    return [f for f in fields if not data.get(f)]


def new_ref(prefix):
    d = datetime.now(); return prefix + '-' + d.strftime('%m%d') + '-' + ''.join(secrets.choice('ABCDEFGHJKMNPQRSTUVWXYZ23456789') for _ in range(6))


def valid_email(v): return bool(re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', v)) and len(v) <= 254


def submit(subject, title, fields, required_fields, prefix='RQ', email_optional=False):
    data = payload(); missing = required(data, required_fields)
    if missing: return jsonify(error='Please complete all required fields.'), 400
    email = data.get('email', '')
    if email_optional and not email: email = ''
    elif not valid_email(email): return jsonify(error='Please enter a valid email address.'), 400
    ref = new_ref(prefix)
    body = title + '\nReference: ' + ref + '\nDate: ' + datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M UTC') + '\n\n' + '\n'.join(f'{label}: {data.get(key) or "Not provided"}' for key, label in fields)
    try:
        send_notice(f'{subject} [{ref}]', body, reply_to=email or None, customer_copy=email or None)
    except Exception as exc:
        app.logger.exception('Email submission failed')
        return jsonify(error=str(exc) if isinstance(exc, RuntimeError) else 'Email delivery is temporarily unavailable. Please try again later.'), 503
    return jsonify(message=f'Your request has been received (reference {ref}).' + (' A confirmation email has been sent to your inbox.' if email else ' Our team will contact you using the details you gave.'), ref=ref), 200


@app.get('/')
def home(): return Response(SITE_HTML, mimetype='text/html')

@app.get('/download')
def download_game():
    # Downloads open only after the launch countdown ends (administrator can always test).
    u = current_user()
    if not (u and u['role'] == 'admin'):
        with closing(db()) as c: row = c.execute("select v from kv where k='launch'").fetchone()
        live = False
        if row:
            try: live = datetime.fromisoformat(row['v']) <= datetime.now(timezone.utc)
            except ValueError: live = False
        if not live:
            return Response('<!doctype html><meta name="viewport" content="width=device-width"><title>Not available yet</title><body style="background:#090b12;color:#fff;font:16px system-ui;padding:40px;max-width:650px;margin:auto"><h1>NAIJA REPUBLIC RP</h1><h2>Download not available yet</h2><p>The game download opens when the launch countdown ends. Please come back then.</p><a style="color:#ffbd42" href="/">Return to the website</a></body>', status=403, mimetype='text/html')
    if APK_URL.startswith('https://'): return redirect(APK_URL, 302)
    apk = BASE / 'game' / 'naija-republic-rp.apk'
    if not apk.is_file():
        return Response('<!doctype html><meta name="viewport" content="width=device-width"><title>Game download</title><body style="background:#090b12;color:#fff;font:16px system-ui;padding:40px;max-width:650px;margin:auto"><h1>NAIJA REPUBLIC RP</h1><h2>Game download is being prepared</h2><p>The official Android APK has not been uploaded yet. Please check back soon.</p><a style="color:#ffbd42" href="/">Return to the website</a></body>', status=503, mimetype='text/html')
    return send_file(apk, as_attachment=True, download_name='Naija-Republic-RP.apk', mimetype='application/vnd.android.package-archive')

RATE_PER_COIN, MIN_COINS, MAX_COINS = 2, 100, 500000
PAY_METHODS = ('Bank transfer', 'PayPal', 'Crypto (USDT)', 'Mobile money', 'Other')
_orders = {}


@app.post('/api/order')
def order():
    d = request.get_json(silent=True) or {}
    ip = client_ip(); now = time.time(); _orders[ip] = [t for t in _orders.get(ip, []) if now - t < 3600]
    if len(_orders[ip]) >= 10: return jsonify(error='Too many orders from this connection. Please try again later.'), 429
    srv = d.get('server'); player = str(d.get('player', '')).strip()[:40]; email = str(d.get('email', '')).strip()[:254]
    method = d.get('method'); region = str(d.get('region', '')).strip()[:80]; estimate = str(d.get('estimate', '')).strip()[:80]
    try: coins = int(d.get('coins'))
    except (TypeError, ValueError): return jsonify(error='Enter a valid number of coins.'), 400
    if srv not in ('Server 01', 'Server 02'): return jsonify(error='Choose Server 01 or Server 02.'), 400
    if not MIN_COINS <= coins <= MAX_COINS: return jsonify(error=f'Coins must be between {MIN_COINS:,} and {MAX_COINS:,}.'), 400
    if not player: return jsonify(error='Enter your character name.'), 400
    if not valid_email(email): return jsonify(error='Enter a valid email address.'), 400
    if method not in PAY_METHODS: return jsonify(error='Choose a payment method.'), 400
    total = coins * RATE_PER_COIN   # price is always calculated on the server
    oid = str(d.get('id', ''))
    with closing(db()) as c:
        if not re.fullmatch(r'NR-\d{4}-[A-Z2-9]{6}', oid) or c.execute('select 1 from orders where id=?', (oid,)).fetchone():
            oid = new_ref('NR')
    body = (f'NAIJA REPUBLIC RP - COIN ORDER\n\nOrder ID: {oid}\nDate: {datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")}\n\n'
            f'Item: {coins:,} in-game coins (Republic coins)\nQuantity: {coins:,}\nRate: N{RATE_PER_COIN} per coin\nTotal: N{total:,}\nEstimate in customer currency: {estimate or "n/a"}\n\n'
            f'Server: {srv}\nCharacter name: {player}\nRegion: {region or "n/a"}\nPayment method: {method}\nCustomer email: {email}\n')
    try:
        send_notice(f'Order {oid}: {coins:,} in-game coins ({srv})', body, reply_to=email, customer_copy=email)
    except Exception as exc:
        app.logger.exception('Order email failed')
        return jsonify(error=str(exc) if isinstance(exc, RuntimeError) else 'Email delivery is temporarily unavailable.'), 503
    _orders[ip].append(now)
    with closing(db()) as c:
        c.execute('insert or ignore into orders(id,ts,email,player,server,coins,total,method,region) values(?,?,?,?,?,?,?,?,?)', (oid, now, email, player, srv, coins, total, method, region)); c.commit()
    return jsonify(ok=True, id=oid, total=total)


