DATA = BASE / 'data'; DATA.mkdir(exist_ok=True)
DB_PATH = DATA / 'site.db'
ADMIN_EMAIL = os.getenv('NR_ADMIN_EMAIL', '').strip().lower()
ADMIN_PASSWORD = os.getenv('NR_ADMIN_PASSWORD', '')
_key = DATA / 'secret.key'
if not os.getenv('NR_SECRET_KEY') and not _key.exists(): _key.write_text(secrets.token_hex(32))
app.secret_key = os.getenv('NR_SECRET_KEY') or _key.read_text().strip()
app.config.update(SESSION_COOKIE_HTTPONLY=True, SESSION_COOKIE_SAMESITE='Lax', SESSION_COOKIE_SECURE=bool(os.getenv('REPLIT_DEPLOYMENT')), PERMANENT_SESSION_LIFETIME=60*60*24*30)

def db():
    c = sqlite3.connect(DB_PATH); c.row_factory = sqlite3.Row; return c

def init_db():
    with closing(db()) as c:
        c.executescript("""create table if not exists users(id integer primary key, email text unique not null, name text, pw text, created real);
        create table if not exists news(id integer primary key, title text, body text, kind text, whn text, img text, ts real);
        create table if not exists kv(k text primary key, v text);
        create table if not exists visitors(vid text primary key, ts real);
        create table if not exists orders(id text primary key, ts real, email text, player text, server text, coins integer, total integer, method text, region text);""")
        c.commit()
init_db()

_fails = {}
def client_ip(): return (request.headers.get('X-Forwarded-For') or request.remote_addr or '').split(',')[0].strip()
def limited(ip):
    now = time.time(); _fails[ip] = [t for t in _fails.get(ip, []) if now - t < 900]; return len(_fails[ip]) >= 8
def fail(ip): _fails.setdefault(ip, []).append(time.time())

def current_user():
    uid = session.get('uid')
    if not uid: return None
    with closing(db()) as c: r = c.execute('select id,email,name from users where id=?', (uid,)).fetchone()
    if not r: return None
    # Admin role comes ONLY from the secret environment email, never from the database.
    return {'id': r['id'], 'email': r['email'], 'name': r['name'], 'role': 'admin' if ADMIN_EMAIL and r['email'] == ADMIN_EMAIL else 'member'}

def public_user(u): return {'name': u['name'], 'email': u['email'], 'role': u['role']} if u else None

def admin_only(f):
    @wraps(f)
    def w(*a, **k):
        u = current_user()
        if not u or u['role'] != 'admin': return jsonify(error='Administrator access required.'), 403
        if request.method != 'GET' and request.method != 'DELETE' and not request.is_json: return jsonify(error='Bad request.'), 400
        return f(*a, **k)
    return w

@app.after_request
def headers(resp):
    resp.headers['X-Content-Type-Options'] = 'nosniff'
    if request.path.startswith('/api/'): resp.headers['Cache-Control'] = 'no-store'
    return resp

@app.post('/api/auth')
def auth():
    if not request.is_json: return jsonify(error='Bad request.'), 400
    d = request.get_json(silent=True) or {}
    mode = d.get('mode'); email = str(d.get('email', '')).strip().lower()[:254]; pw = str(d.get('password', ''))[:200]; name = str(d.get('name', '')).strip()[:40]
    ip = client_ip()
    if limited(ip): return jsonify(error='Too many attempts. Please try again in a few minutes.'), 429
    if not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', email) or len(pw) < 8:
        fail(ip); return jsonify(error='Enter a valid email and a password of at least 8 characters.'), 400
    if mode == 'join' and str(d.get('confirm', ''))[:200] != pw: return jsonify(error='Passwords do not match.'), 400
    with closing(db()) as c:
        if ADMIN_EMAIL and email == ADMIN_EMAIL:
            # Permanent administrator: the password is checked against the secret, never stored.
            if not ADMIN_PASSWORD or not hmac.compare_digest(pw.encode(), ADMIN_PASSWORD.encode()):
                fail(ip); return jsonify(error='Incorrect email or password.'), 401
            c.execute('insert or ignore into users(email,name,pw,created) values(?,?,?,?)', (email, name or 'Administrator', '', time.time())); c.commit()
        elif mode == 'join':
            if not name: return jsonify(error='Enter a display name.'), 400
            if c.execute('select 1 from users where email=?', (email,)).fetchone(): return jsonify(error='An account with this email already exists. Please sign in.'), 409
            c.execute('insert into users(email,name,pw,created) values(?,?,?,?)', (email, name, generate_password_hash(pw), time.time())); c.commit()
        else:
            r = c.execute('select pw from users where email=?', (email,)).fetchone()
            if not r or not r['pw'] or not check_password_hash(r['pw'], pw):
                fail(ip); return jsonify(error='Incorrect email or password.'), 401
        uid = c.execute('select id from users where email=?', (email,)).fetchone()['id']
    session.clear(); session['uid'] = uid; session.permanent = True
    return jsonify(user=public_user(current_user()))

@app.post('/api/logout')
def logout(): session.clear(); return jsonify(ok=True)

@app.get('/api/me')
def me(): return jsonify(user=public_user(current_user()))

@app.post('/api/visit')
def visit():
    vid = request.cookies.get('nr_vid', '')
    new = not re.fullmatch(r'[A-Za-z0-9_-]{10,40}', vid)
    if new: vid = secrets.token_urlsafe(12)
    with closing(db()) as c: c.execute('insert or ignore into visitors(vid,ts) values(?,?)', (vid, time.time())); c.commit()
    resp = jsonify(ok=True)
    if new: resp.set_cookie('nr_vid', vid, max_age=60*60*24*365, httponly=True, samesite='Lax', secure=bool(os.getenv('REPLIT_DEPLOYMENT')))
    return resp

@app.get('/api/site')
def site():
    with closing(db()) as c:
        online = c.execute('select count(*) n from visitors').fetchone()['n']
        row = c.execute("select v from kv where k='launch'").fetchone()
        news = [dict(id=r['id'], title=r['title'], body=r['body'], kind=r['kind'], when=r['whn'], img=r['img'], ts=int(r['ts'] * 1000)) for r in c.execute('select * from news order by ts desc limit 30')]
        with closing(db()) as c: crow = c.execute("select v from kv where k='community'").fetchone()
    return jsonify(online=max(1, online), launch=row['v'] if row else None, community=int(crow['v']) if crow else 0, news=news)

@app.post('/api/admin/news')
@admin_only
def admin_news():
    d = request.get_json(silent=True) or {}
    title = str(d.get('title', '')).strip()[:120]; body = str(d.get('body', '')).strip()[:4000]; when = str(d.get('when', '')).strip()[:60]
    kind = d.get('kind') if d.get('kind') in ('News', 'Update', 'Event') else 'News'
    img = str(d.get('img', ''))
    if not title or not body: return jsonify(error='Add a title and write-up.'), 400
    if img and (len(img) > 260000 or not re.match(r'^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$', img)): return jsonify(error='Picture is not valid or too large.'), 400
    with closing(db()) as c: c.execute('insert into news(title,body,kind,whn,img,ts) values(?,?,?,?,?,?)', (title, body, kind, when, img, time.time())); c.commit()
    return jsonify(ok=True)

@app.delete('/api/admin/news/<int:nid>')
@admin_only
def admin_news_delete(nid):
    with closing(db()) as c: c.execute('delete from news where id=?', (nid,)); c.commit()
    return jsonify(ok=True)

@app.post('/api/admin/launch')
@admin_only
def admin_launch():
    v = str((request.get_json(silent=True) or {}).get('launch', '')).strip()
    if v:
        try: v = datetime.fromisoformat(v.replace('Z', '+00:00')).astimezone(timezone.utc).isoformat()
        except ValueError: return jsonify(error='Invalid date.'), 400
    with closing(db()) as c:
        if v: c.execute("insert or replace into kv(k,v) values('launch',?)", (v,))
        else: c.execute("delete from kv where k='launch'")
        c.commit()
    return jsonify(ok=True)

@app.post('/api/admin/community')
@admin_only
def admin_community():
    try: n = int((request.get_json(silent=True) or {}).get('community', 0))
    except (TypeError, ValueError): return jsonify(error='Enter a valid number.'), 400
    if not 0 <= n <= 10000000: return jsonify(error='Enter a valid number.'), 400
    with closing(db()) as c:
        if n: c.execute("insert or replace into kv(k,v) values('community',?)", (str(n),))
        else: c.execute("delete from kv where k='community'")
        c.commit()
    return jsonify(ok=True)

